<?php
$from=(int)($_GET['from']??0); $to=(int)($_GET['to']??0); $date=$_GET['date']??date('Y-m-d',strtotime('+1 day'));
$stations=db()->query('SELECT id,name,code FROM stations ORDER BY name')->fetchAll();
$results=[]; if($from && $to && $from!==$to && preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)) { $q=db()->prepare("SELECT t.*,r.train_code,r.base_fare,a.name origin,b.name destination,(SELECT COUNT(*) FROM trip_seats ts WHERE ts.trip_id=t.id AND ts.status='available') available FROM trips t JOIN routes r ON r.id=t.route_id JOIN stations a ON a.id=r.from_station_id JOIN stations b ON b.id=r.to_station_id WHERE r.from_station_id=? AND r.to_station_id=? AND DATE(t.depart_at)=? ORDER BY t.depart_at"); $q->execute([$from,$to,$date]); $results=$q->fetchAll(); }
?>
<section class="page-banner"><div class="container"><p class="eyebrow">PLAN YOUR NEXT RAIL JOURNEY</p><h1>Find a train <em>that fits.</em></h1><p>Browse sample schedules and fares for your travel date.</p></div></section><section class="container content-section"><form class="search-panel" method="get"><input type="hidden" name="page" value="search"><label>Leaving from<select name="from" required><option value="">Select station</option><?php foreach($stations as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $from===$s['id']?'selected':'' ?>><?= h($s['name']) ?> (<?= h($s['code']) ?>)</option><?php endforeach; ?></select></label><label>Going to<select name="to" required><option value="">Select station</option><?php foreach($stations as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $to===$s['id']?'selected':'' ?>><?= h($s['name']) ?> (<?= h($s['code']) ?>)</option><?php endforeach; ?></select></label><label>Travel date<input type="date" name="date" value="<?= h($date) ?>" min="<?= date('Y-m-d') ?>" required></label><button class="button primary">Search trains →</button></form>
<?php if($from && $to): ?><div class="results-heading"><div><p class="eyebrow">AVAILABLE SAMPLE DEPARTURES</p><h2><?= h(date('D, d M Y',strtotime($date))) ?></h2></div><span class="pill"><?= count($results) ?> trains found</span></div><?php if(!$results): ?><div class="empty-state"><span>⌁</span><h3>No trains found for this search</h3><p>Try Kuala Lumpur to Ipoh or choose another date. Sample schedules are provided for demo purposes.</p></div><?php else: ?><div class="train-list"><?php foreach($results as $t): ?><article class="train-card"><div class="train-name"><span class="train-icon">↗</span><span><strong><?= h($t['train_code']) ?></strong><small>Intercity · Standard</small></span></div><div class="time-point"><strong><?= h(date('H:i',strtotime($t['depart_at']))) ?></strong><small><?= h($t['origin']) ?></small></div><div class="duration"><span></span><small><?= h(round((strtotime($t['arrive_at'])-strtotime($t['depart_at']))/3600,1)) ?> hours</small></div><div class="time-point"><strong><?= h(date('H:i',strtotime($t['arrive_at']))) ?></strong><small><?= h($t['destination']) ?></small></div><div class="fare"><strong><?= money((float)$t['base_fare']) ?></strong><small><?= (int)$t['available'] ?> seats left</small></div><a class="button primary small" href="?page=seats&trip=<?= (int)$t['id'] ?>">Select seats</a></article><?php endforeach; ?></div><?php endif; ?><?php else: ?><div class="hint-card"><span class="hint-mark">i</span><p>Choose your departure, destination and date to see available trains.</p></div><?php endif; ?></section>
